def transpose_rows(rows):
    if not rows:
        return []

    # Find the length of the first row to determine the number of columns
    num_cols = len(rows[0])

    # Create a new list of lists with the same number of rows as the original and the same number of columns as the first row
    transposed = [[None] * num_cols for _ in range(len(rows))]

    # Populate the transposed matrix
    for i in range(num_cols):
        for j in range(len(rows)):
            transposed[i][j] = rows[j][i]

    return transposed

def longest_zero_run(values):
    max_length = 0
    current_length = 0

    for value in values:
        if value == 0:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 0

    return max_length if max_length > 0 else 0

def count_words(text):
    # Split text into words based on whitespace
    words = text.split()

    # Convert all words to lowercase
    words = [word.lower() for word in words]

    # Create a dictionary to store word counts
    word_counts = {}

    # Count occurrences of each word
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    return word_counts

import re

def count_words(text):
    # Remove punctuation and split text into words
    words = re.findall(r'\b\w+\b', text.lower())

    # Create a dictionary to store word counts
    word_counts = {}

    # Count occurrences of each word
    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    return word_counts

def edges_to_adjacency(n, edges):
    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)
    return adj_list

def merge_sorted_unique(a, b):
    result = []
    i, j = 0, 0

    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            if a[i] not in result:
                result.append(a[i])
            i += 1
        elif a[i] > b[j]:
            if b[j] not in result:
                result.append(b[j])
            j += 1
        else:
            if a[i] not in result:
                result.append(a[i])
            i += 1
            j += 1

    # Append remaining elements from both lists
    result.extend(a[i:])
    result.extend(b[j:])

    return result
